#!/usr/bin/env python3
import sys, json, re, zipfile, shutil, os

TEMPLATE = 'inputs/offer_letter_template.docx'
DATA = 'inputs/employee_data.json'
OUT = 'output/offer_letter_filled.docx'

PART_RE = re.compile(r'word/(document|header\d+|footer\d+)\.xml$')

def fail(msg):
    sys.stderr.write("ERROR: " + msg + "\n")
    sys.exit(2)

with open(DATA, encoding='utf-8') as f:
    data = json.load(f)

# Conditional governing field
GOV = 'RELOCATION_PACKAGE'

# token patterns
PLACEHOLDER = re.compile(r'\{\{([A-Z_][A-Z0-9_]*)\}\}')
IF_RE = re.compile(r'\{\{IF_RELOCATION\}\}')
ENDIF_RE = re.compile(r'\{\{END_IF_RELOCATION\}\}')

T_RE = re.compile(r'(<w:t\b[^>]*>)(.*?)(</w:t>)', re.S)
P_RE = re.compile(r'<w:p\b.*?</w:p>', re.S)

missing = set()
used = set()
conditional_present = False

def resolve_placeholders(text):
    def repl(m):
        key = m.group(1)
        if key in ('IF_RELOCATION', 'END_IF_RELOCATION'):
            return m.group(0)  # handled separately
        used.add(key)
        if key not in data:
            missing.add(key)
            return m.group(0)
        return str(data[key])
    return PLACEHOLDER.sub(repl, text)

def xml_escape(s):
    return s.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')

def xml_unescape(s):
    return s.replace('&lt;', '<').replace('&gt;', '>').replace('&amp;', '&')

def process_paragraph(ptext):
    global conditional_present
    # gather w:t nodes
    nodes = list(T_RE.finditer(ptext))
    if not nodes:
        return ptext
    # concatenate unescaped text
    merged = ''.join(xml_unescape(n.group(2)) for n in nodes)

    changed = False

    # Handle conditional (single-paragraph only)
    if IF_RE.search(merged) or ENDIF_RE.search(merged):
        conditional_present = True
        if GOV not in data:
            missing.add(GOV)
            keep = None
        else:
            keep = (str(data[GOV]) == 'Yes')
        # Replace IF...ENDIF block
        def cond_repl(m):
            inner = m.group(1)
            return inner if keep else ''
        new = re.sub(r'\{\{IF_RELOCATION\}\}(.*?)\{\{END_IF_RELOCATION\}\}',
                     cond_repl, merged, flags=re.S)
        if keep is None:
            # leave for failure; don't strip
            new = merged
        merged = new
        changed = True

    # Replace placeholders
    new2 = resolve_placeholders(merged)
    if new2 != merged or changed:
        merged = new2
        changed = True

    if not changed:
        return ptext

    # Redistribute: first node carries full text, rest emptied
    result = []
    last = 0
    first_done = False
    for n in nodes:
        result.append(ptext[last:n.start()])
        open_tag, _, close_tag = n.group(1), n.group(2), n.group(3)
        if not first_done:
            # ensure preserve space
            ot = open_tag
            if 'xml:space' not in ot:
                ot = ot[:-1] + ' xml:space="preserve">'
            result.append(ot + xml_escape(merged) + close_tag)
            first_done = True
        else:
            ot = open_tag
            if 'xml:space' not in ot:
                ot = ot[:-1] + ' xml:space="preserve">'
            result.append(ot + close_tag)
        last = n.end()
    result.append(ptext[last:])
    return ''.join(result)

def process_part(xml):
    return P_RE.sub(lambda m: process_paragraph(m.group(0)), xml)

# Read all parts
zin = zipfile.ZipFile(TEMPLATE, 'r')
items = {}
for info in zin.infolist():
    items[info.filename] = zin.read(info.filename)

for name in list(items):
    if PART_RE.match(name):
        xml = items[name].decode('utf-8')
        items[name] = process_part(xml).encode('utf-8')

zin.close()

# Validation
if missing:
    fail("Missing required field(s): " + ", ".join(sorted(missing)))

os.makedirs('output', exist_ok=True)
zout = zipfile.ZipFile(OUT, 'w', zipfile.ZIP_DEFLATED)
# preserve original order
for info in zipfile.ZipFile(TEMPLATE, 'r').infolist():
    zout.writestr(info, items[info.filename])
zout.close()

print("OK: wrote", OUT)
print("Conditional present:", conditional_present, "| RELOCATION_PACKAGE =", data.get(GOV))
print("Used fields:", sorted(used))
